head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
eval함수는 자동변환에 제약이 많습니다. ASIS소스 확인 후 변환해주세요.
eval함수 사용 수: 1

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDSTF52000.xml";
scwin.gMsg;
scwin.gType;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 세션의 시장구분


//부서설정
scwin.fn_setCode = function() {
    if (scwin.gDepCd == '' || scwin.gDepCd == "ZSYS") {
        scwin.gDepCd = '';
        $c.cm.setColumnProp(grd_Grid, 'DEP_NM', 'show', true);
    }
    if (scwin.gLdMktTp == "9") {
        $c.stf.setObjectValue(rdo_MktTpCd, '1');
        $c.stf.showObj(label_7, true);
        $c.stf.showObj(rdo_MktTpCd, true);
    } else {
        $c.stf.setObjectValue(rdo_MktTpCd, scwin.gLdMktTp);
    }
};
scwin.fn_setHeader = function() {
    cmb_corpcd.setDisabled(true);
    dts_read.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CONTACTPNT_INOUT";
    dts_read.Reset();
    dts_read.insertRow();
};


//담당자목록
scwin.fn_list = function() {
    var url = "/Mypage.do?method=listRepContactpnt&inputMessageId=CONTACTPNT_INOUT" + "&outputMessageId=CONTACTPNT_INOUT" + "&DEP_CD=" + scwin.gDepCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_list.DataID = encodeURI(url);
    dts_list.Reset();
};



//법인사용자구분
scwin.fn_listCorp = function() {
    var url = "/Mypage.do?method=listRepContactpntCorp&inputMessageId=CORPLIST_INOUT&outputMessageId=CORPLIST_INOUT" + "&For=C" + "&DEP_CD=" + scwin.gDepCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_corplist.DataID = encodeURI(url);
    dts_corplist.Reset();
};
scwin.fn_approval = function(approvType) {
    var rtn;
    var vScrenTpCD;
    if (approvType == 'N' || approvType == 'C') {
        if ($c.stf.getObjectValue(cmb_corpcd) == "") {
            $c.win.alert("[법인사용자구분]을 선택하세요");
            cmb_corpcd.focus();
            return;
        }
        if ($c.stf.getObjectValue(txb_chrgnm) == "") {
            $c.win.alert("[담당팀/담당자명]을 입력하세요");
            txb_chrgnm.focus();
            return;
        }
        if (!scwin.checkMaxLength1(txb_chrgnm, 80, "[담당팀/담당자명]")) {
            txb_chrgnm.focus();
            return;
        }
        if ($c.stf.getObjectValue(txb_tel) == "") {
            $c.win.alert("[전화번호(TEL)]을 입력하세요");
            txb_tel.focus();
            return;
        }
        if (!scwin.checkMaxLength1(txb_tel, 80, "[전화번호(TEL)]")) {
            txb_tel.focus();
            return;
        }
        if (!scwin.checkMaxLength1(txb_fax, 80, "[팩스번호(FAX)]")) {
            txb_fax.focus();
            return;
        }
        if (!scwin.checkMaxLength1(txb_email, 80, "[이메일(EMAIL)]")) {
            txb_email.focus();
            return;
        }
        if (approvType == 'N') {
            scwin.gMsg = "등록";
            vScrenTpCD = SCREN_PROCS_TP_CD_02;
            rtn = confirm('등록 하시겠습니까?');
        } else if (approvType == 'C') {
            scwin.gMsg = "변경";
            vScrenTpCD = SCREN_PROCS_TP_CD_03;
            rtn = confirm('변경 하시겠습니까?');
        }
    } else if (approvType == 'D') {
        scwin.gMsg = "삭제";
        vScrenTpCD = SCREN_PROCS_TP_CD_04;
        rtn = confirm('삭제 하시겠습니까?');
    }
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_read.setCellData(1, "CONTN_ID", approvType);
        dts_read.setCellData(1, "USR_ID", scwin.gEmpNo);
        dts_read.setCellData(1, "LD_MKT_TP_CD", $c.stf.getObjectValue(rdo_MktTpCd));
        trs_Save.Action = "/Mypage.do?method=regRepContactpnt&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenTpCD;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_read)";
        trs_Save.Post();
    }
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.dts_list_OnLoadCompleted = function(rowcount) {
    if (dts_list.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + dts_list.errorMsg);
    } else {
        if (rowcount <= 0) {
            dts_list.removeAll();
        }
    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "담당자 정보 " + scwin.gMsg));
    dts_read.removeAll();
    scwin.fn_setHeader();
    scwin.fn_list();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "담당자 정보" + scwin.gMsg));
};
scwin.grd_Grid_OnClick = function(row, colid) {
    if (row >= 1) {
        cmb_corpcd.BindColVal = dts_list.getCellData(row, "CORP_USR_TP_CD");
        txb_chrgnm.setValue(dts_list.getCellData(row, "CHRG_NM"));
        txb_tel.setValue(dts_list.getCellData(row, "CHRG_TEL_NO"));
        txb_fax.setValue(dts_list.getCellData(row, "FAX_NO"));
        txb_email.setValue(dts_list.getCellData(row, "EMAIL"));
        txb_seq.setValue(dts_list.getCellData(row, "BYDD_SEQ"));
        rdo_MktTpCd.setValue(dts_list.getCellData(row, "LD_MKT_TP_CD"));
        cmb_corpcd.setDisabled(true);
        if (colid == "ACTDEL") {
            scwin.gType = 'D'; //삭제
            scwin.fn_approval(scwin.gType);
        }
    }
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_chg_onclick = function() {
    if ($c.stf.getObjectValue(txb_seq) != '') {
        scwin.gType = 'C'; //변경

    } else {
        scwin.gType = 'N'; //신규

    }
    scwin.fn_approval(scwin.gType);
};
scwin.btn_clear_onclick = function() {
    cmb_corpcd.setDisabled(true);
    cmb_corpcd.BindColVal = "";
    txb_chrgnm.setValue("");
    txb_tel.setValue("");
    txb_fax.setValue("");
    txb_email.setValue("");
    txb_seq.setValue("");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.showObj(txb_seq, false);
    $c.stf.showObj(label_7, false);
    $c.stf.showObj(rdo_MktTpCd, false);
    scwin.fn_setCode();
    scwin.fn_setHeader();
    scwin.fn_list();
    scwin.fn_listCorp();
};
